import test from 'node:test';
import { normalizeEmail, normalizePhone } from './normalize.js';

test('normalizes email', () => {
  assert.equal(normalizeEmail(' A@B.COM '), 'a@b.com');
});

test('returns phone', () => {
  assert.equal(normalizePhone('123'), '123');
});

